CREATE TRIGGER UNDGVersion_Version_Create
	ON UNDGVersion
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT DV_PK, 'DV'
	FROM inserted
GO
CREATE TRIGGER UNDGVersion_Version_Update
	ON UNDGVersion
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON DV_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER UNDGVersion_DataChangeHistory
	ON UNDGVersion
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT DV_PK, 'DV' FROM inserted
	UNION
	SELECT DV_PK, 'DV' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER UNDGVersion_DataProcessingResult_Delete
	ON UNDGVersion
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.DV_PK
	END
